// Meta CAPI — normaliza, faz SHA-256 e monta o evento Lead.
// Aceita o item do Webhook ({ body, headers }) ou o item repassado por outro fluxo.

function sha256(ascii) {
  // SHA-256 em JS puro (UTF-8 -> hex minúsculo), sem depender do módulo crypto.
  const utf8 = unescape(encodeURIComponent(ascii));
  const K = [], H = [];
  let n = 2, found = 0;
  const frac = (x) => ((x - Math.floor(x)) * 0x100000000) | 0;
  outer: while (found < 64) {
    for (let f = 2; f * f <= n; f++) if (n % f === 0) { n++; continue outer; }
    if (found < 8) H[found] = frac(Math.pow(n, 1 / 2));
    K[found++] = frac(Math.pow(n, 1 / 3));
    n++;
  }
  const words = [];
  const bitLen = utf8.length * 8;
  let msg = utf8 + "\x80";
  while (msg.length % 64 !== 56) msg += "\x00";
  for (let i = 0; i < msg.length; i++) words[i >> 2] |= msg.charCodeAt(i) << ((3 - (i % 4)) * 8);
  words.push(Math.floor(bitLen / 0x100000000), bitLen | 0);
  const rotr = (x, r) => (x >>> r) | (x << (32 - r));
  const h = H.slice();
  for (let j = 0; j < words.length; j += 16) {
    const w = words.slice(j, j + 16);
    const [a0, b0, c0, d0, e0, f0, g0, h0] = h;
    let a = a0, b = b0, c = c0, d = d0, e = e0, f = f0, g = g0, hh = h0;
    for (let i = 0; i < 64; i++) {
      if (i >= 16) {
        const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
        const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
        w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
      }
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + (w[i] | 0)) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      hh = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    h[0] = (h[0] + a) | 0; h[1] = (h[1] + b) | 0; h[2] = (h[2] + c) | 0; h[3] = (h[3] + d) | 0;
    h[4] = (h[4] + e) | 0; h[5] = (h[5] + f) | 0; h[6] = (h[6] + g) | 0; h[7] = (h[7] + hh) | 0;
  }
  return h.map((x) => (x >>> 0).toString(16).padStart(8, "0")).join("");
}

const cfg = $("Configuração").first().json;
const out = [];

for (const item of $input.all()) {
  const src = item.json.body ? item.json : { body: item.json, headers: item.json.headers || {} };
  const b = src.body || {};
  const headers = src.headers || {};
  const lead = b.lead || {};
  const ctx = b.context || {};
  const attr = b.attribution || {};

  // Normalização (a mesma do Pixel no navegador)
  const email = String(b.email || lead.email || "").trim().toLowerCase().replace(/\s+/g, "");
  let phone = String(b.phone_e164 || lead.whatsapp || "").replace(/\D/g, "");
  if (phone && !phone.startsWith("55")) phone = "55" + phone;
  const fullName = String(lead.name || "").trim().split(/\s+/);
  const fn = String(b.first_name || lead.first_name || fullName[0] || "").trim().toLowerCase();
  const ln = String(b.last_name || (fullName.length > 1 ? fullName[fullName.length - 1] : "")).trim().toLowerCase();
  const st = String(b.state || lead.state || "").trim().toLowerCase();
  const externalId = String(b.external_id || b.event_id || "").trim();

  // IP do lead: primeiro IP do x-forwarded-for (o POST sai do navegador)
  const xff = String(headers["x-forwarded-for"] || headers["X-Forwarded-For"] || "");
  const ip = xff.split(",")[0].trim() || String(headers["x-real-ip"] || "").trim();

  const userData = { country: [sha256("br")] };
  if (email) userData.em = [sha256(email)];
  if (phone) userData.ph = [sha256(phone)];
  if (fn) userData.fn = [sha256(fn)];
  if (ln) userData.ln = [sha256(ln)];
  if (/^[a-z]{2}$/.test(st)) userData.st = [sha256(st)];
  if (externalId) userData.external_id = [sha256(externalId)];
  // Sem hash:
  const fbp = b.fbp || attr.fbp;
  const fbc = b.fbc || attr.fbc;
  if (fbp) userData.fbp = fbp;
  if (fbc) userData.fbc = fbc;
  if (ip) userData.client_ip_address = ip;
  const ua = b.user_agent || ctx.user_agent || headers["user-agent"];
  if (ua) userData.client_user_agent = ua;

  // event_time: unix em segundos; fora da janela aceita pela Meta (7 dias), usa agora
  const now = Math.floor(Date.now() / 1000);
  let eventTime = Number(b.event_time) || Math.floor(Date.parse(b.timestamp || "") / 1000) || now;
  if (eventTime > now || eventTime < now - 7 * 24 * 3600) eventTime = now;

  const event = {
    event_name: "Lead",
    event_time: eventTime,
    event_id: String(b.event_id || ""),
    action_source: "website",
    event_source_url: b.event_source_url || ctx.page_url || "",
    user_data: userData,
    custom_data: {
      content_name: b.content_name || "Ebook Mar Azul",
      lead_profile: b.perfil || lead.role || "",
      lead_state: st.toUpperCase(),
    },
  };

  const body = { data: [event] };
  const testCode = String(cfg.TEST_EVENT_CODE || "").trim();
  if (testCode) body.test_event_code = testCode;

  out.push({
    json: {
      graph_version: String(cfg.GRAPH_VERSION || "v26.0").trim(),
      pixel_id: String(cfg.PIXEL_ID || "29379423411743032").trim(),
      capi_body: body,
      event_id: event.event_id,
    },
  });
}

return out;

// A Meta respondeu erro (ou não respondeu). Registra e segue: o lead já foi salvo pelo fluxo principal.
return $input.all().map((item) => {
  const sent = $("Normalizar + SHA-256").all()[0]?.json || {};
  const log = {
    quando: new Date().toISOString(),
    event_id: sent.event_id || "",
    erro: item.json.error || item.json,
  };
  console.error("[Meta CAPI] falha ao enviar Lead", JSON.stringify(log));
  return { json: log };
});
